import { useCallback, useEffect, useMemo, useState } from 'react'
import { Activity, ArrowDownToLine, ArrowRight, Bell, Bot, Boxes, Check, CheckSquare, ChevronDown, CircleHelp, ClipboardList, Command, Compass, FileText, Gauge, LayoutDashboard, Menu, Plus, Search, Settings, ShieldAlert, Sparkles, Trash2, Users, X, Pencil, Archive, RotateCcw } from 'lucide-react'

const API=import.meta.env.VITE_API_URL||'http://localhost:8000/api'
