 const saveSolution=()=>action(()=>api(`/projects/${project!.id}/solution`,json('PUT',{solution})))
 const generateRoadmap=async()=>{setBusy(true);try{const r=await api('/roadmap',json('POST',{project_id:project!.id,analysis,solution,team:members,deadline:project!.deadline}));setMode(r.mode);await refresh(project!.id)}catch(e:any){setError(e.message)}finally{setBusy(false)}}
 const analyzeRisks=async()=>{setBusy(true);try{const r=await api(`/projects/${project!.id}/risks/analyze`,{method:'POST'});setRisks(r.result.risks||[]);setRiskLabel(r.label);setMode(r.mode)}catch(e:any){setError(e.message)}finally{setBusy(false)}}
 const allocate=async()=>{setBusy(true);try{const r=await api(`/projects/${project!.id}/allocate`,{method:'POST'});setMode(r.mode);await refresh(project!.id);setError(r.label)}catch(e:any){setError(e.message)}finally{setBusy(false)}}
 const generateDocs=async()=>{setBusy(true);try{const r=await api(`/projects/${project!.id}/documents/generate`,{method:'POST'});setDoc(r.result.content);setMode(r.mode);await refresh(project!.id)}catch(e:any){setError(e.message)}finally{setBusy(false)}}
 const saveDoc=()=>action(()=>api(`/projects/${project!.id}/documents`,json('POST',{title:'README.md',content:doc})))
 const download=()=>{const u=URL.createObjectURL(new Blob([doc],{type:'text/markdown'})),a=document.createElement('a');a.href=u;a.download='README.md';a.click();URL.revokeObjectURL(u)}
 const editProject=()=>action(()=>api(`/projects/${project!.id}`,json('PATCH',{name:form.name,description:form.description||'',hackathon_name:form.hackathon_name||'',start_date:form.start_date||null,deadline:form.deadline||null,status:form.status||'Planning',problem_statement:project!.problem_statement||''})))
 const removeProject=(p:Project)=>{if(confirm(`Delete â€œ${p.name}â€ and all its saved information?`))action(async()=>{await api(`/projects/${p.id}`,{method:'DELETE'});if(activeId===p.id){setProject(null);setActiveId(null);sessionStorage.removeItem('buildpilot-project')}})}
 const archiveProject=(p:Project)=>action(()=>api(`/projects/${p.id}/archive`,{method:'POST'}))
